+        ShowToast("Changes discarded.", "info");
+    }
+
+    // Notification actions
+    private async Task SaveNotifications()
+    {
+        var prefs = new NotificationPrefs(NotifEmail, NotifPush, NotifWeeklyDigest,
+            MutedChannels.Where(c => c.IsMuted).Select(c => c.Name).ToList());
+        await SettingsService.SaveNotificationPrefsAsync(prefs);
+        ShowToast("Notification preferences saved!", "success");
+    }
+
+    // Security actions
+    private async Task UpdatePassword()
+    {
+        if (string.IsNullOrWhiteSpace(CurrentPassword) || string.IsNullOrWhiteSpace(NewPassword))
+        {
+            ShowToast("Please fill in all password fields.", "error");
+            return;
+        }
+        if (NewPassword != ConfirmPassword)
+        {
+            ShowToast("New passwords do not match.", "error");
+            return;
+        }
+        await SettingsService.ChangePasswordAsync(CurrentPassword, NewPassword);
+        CurrentPassword = "";
+        NewPassword = "";
+        ConfirmPassword = "";
+        ChangePasswordExpanded = false;
+        _securitySettings = await SettingsService.GetSecuritySettingsAsync();
+        ShowToast("Password updated successfully!", "success");
+    }
+
+    private void RequestRevoke(string sessionId)
+    {
+        _sessionToRevoke = sessionId;
+        ShowRevokeConfirmation = true;
+    }
+
+    private void CancelRevoke()
+    {
+        _sessionToRevoke = null;
+        ShowRevokeConfirmation = false;
+    }
+
+    private async Task ConfirmRevoke()
+    {
+        if (_sessionToRevoke is not null)
+        {
+            await SettingsService.RevokeSessionAsync(_sessionToRevoke);
+            _securitySettings = await SettingsService.GetSecuritySettingsAsync();
+            ShowToast("Session revoked.", "success");
+        }
+        ShowRevokeConfirmation = false;
+        _sessionToRevoke = null;
+    }
+
+    // Appearance actions
+    private async Task SaveAppearance()
+    {
+        var settings = new AppearanceSettings(SelectedTheme, SelectedFontSize, SelectedLanguage, CompactMode);
+        await SettingsService.SaveAppearanceAsync(settings);
+        ShowToast("Appearance settings saved!", "success");
+    }
+
+    // Toast helper
+    private void ShowToast(string message, string type)
+    {
+        _toastCts?.Cancel();
+        ToastMessage = message;
+        ToastType = type;
+        _toastCts = new CancellationTokenSource();
+        var token = _toastCts.Token;
+        _ = Task.Run(async () =>
+        {
+            await Task.Delay(3000, token);
+            if (!token.IsCancellationRequested)
+            {
+                await InvokeAsync(() =>
+                {
+                    ToastMessage = null;
+                    StateHasChanged();
+                });
+            }
+        }, token);
+    }
